/// The dimension style table of a drawing (ISO or ANSI), in live's order.
pub(super) fn dim_styles(iso: bool) -> &'static [(&'static str, &'static [(u16, &'static str)])] {
    if iso { DIM_STYLES_ISO } else { DIM_STYLES_ANSI }
}

/// The table's lengths in mm (ANSI's are in inches).
pub(super) fn table_mm(iso: bool) -> f64 {
    if iso { 1.0 } else { 25.4 }
}

/// The Onshape dimension style family of a drawing (live: "Onshape-ISO-25"
/// in ISO drawings, "Onshape-Standard" in ANSI ones), `$N` per type.
pub(super) fn family(iso: bool) -> &'static str {
    if iso { "Onshape-ISO-25" } else { "Onshape-Standard" }
}

/// Set the dimension variable of DXF group `code` from live's value;
/// lengths times `len` (the table's unit to the export units).
pub(super) fn set_dimvar(ds: &mut DimStyle, code: u16, v: &str, len: f64) {
    let f = v.parse::<f64>().unwrap_or(0.0);
    let i = v.parse::<i16>().unwrap_or(0);
    let b = v != "0";
    match code {
        3 => ds.dimpost = v.to_string(),
        4 => ds.dimapost = v.to_string(),
        40 => ds.dimscale = f,
        41 => ds.dimasz = f * len,
        42 => ds.dimexo = f * len,
        43 => ds.dimdli = f * len,
        44 => ds.dimexe = f * len,
        45 => ds.dimrnd = f * len,
        46 => ds.dimdle = f * len,
        47 => ds.dimtp = f * len,
        48 => ds.dimtm = f * len,
        49 => ds.dimfxl = f * len,
        50 => ds.dimjogang = f,
        69 => ds.dimtfill = i,
        71 => ds.dimtol = b,
        72 => ds.dimlim = b,
        73 => ds.dimtih = b,
        74 => ds.dimtoh = b,
        75 => ds.dimse1 = b,
        76 => ds.dimse2 = b,
        77 => ds.dimtad = i,
        78 => ds.dimzin = i,
        79 => ds.dimazin = i,
        90 => ds.dimarcsym = i,
        140 => ds.dimtxt = f * len,
        141 => ds.dimcen = f * len,
        142 => ds.dimtsz = f * len,
        143 => ds.dimaltf = f,
        144 => ds.dimlfac = f,
        145 => ds.dimtvp = f,
        146 => ds.dimtfac = f,
        147 => ds.dimgap = f * len,
        148 => ds.dimaltrnd = f,
        170 => ds.dimalt = b,
        171 => ds.dimaltd = i,
        172 => ds.dimtofl = b,
        173 => ds.dimsah = b,
        174 => ds.dimtix = b,
        175 => ds.dimsoxd = b,
        176 => ds.dimclrd = i,
        177 => ds.dimclre = i,
        178 => ds.dimclrt = i,
        179 => ds.dimadec = i,
        270 => ds.dimunit = i,
        271 => ds.dimdec = i,
        272 => ds.dimtdec = i,
        273 => ds.dimaltu = i,
        274 => ds.dimalttd = i,
        275 => ds.dimaunit = i,
        276 => ds.dimfrac = i,
        277 => ds.dimlunit = i,
        278 => ds.dimdsep = i,
        279 => ds.dimtmove = i,
        280 => ds.dimjust = i,
        281 => ds.dimsd1 = b,
        282 => ds.dimsd2 = b,
        283 => ds.dimtolj = i,
        284 => ds.dimtzin = i,
        285 => ds.dimaltz = i,
        286 => ds.dimalttz = i,
        287 => ds.dimfit = i,
        288 => ds.dimupt = b,
        289 => ds.dimatfit = i,
        340 => ds.dimtxsty = v.to_string(),
        371 => ds.dimlwd = i,
        372 => ds.dimlwe = i,
        _ => {}
    }
}
